        var content=new StackPanel();var scroll=new ScrollViewer{Content=content,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};Grid.SetRow(scroll,1);ContentHost.Children.Add(scroll);
        var pair=new Grid{Margin=new Thickness(0,0,0,12)};pair.ColumnDefinitions.Add(new(){Width=new GridLength(1,GridUnitType.Star)});pair.ColumnDefinitions.Add(new(){Width=new GridLength(12)});pair.ColumnDefinitions.Add(new(){Width=new GridLength(1,GridUnitType.Star)});pair.Children.Add(cpu.Root);Grid.SetColumn(gpu.Root,2);pair.Children.Add(gpu.Root);content.Children.Add(pair);
