    async Task VisibilityChanged(){int version=++revision;bool visible=IsVisible&&!closed;if(!visible){foreach(var graph in new[]{cpu.Graph,gpu.Graph,ramGraph,diskGraph,networkGraph})graph.Stop();}await lifecycle.WaitAsync();try{await telemetry.StopAsync();if(version!=revision||!IsVisible||closed)return;latest=null;live.Text="Préparation des capteurs…";live.Foreground=UI.Dim;storageKey="";foreach(var graph in new[]{cpu.Graph,gpu.Graph,ramGraph,diskGraph,networkGraph})graph.Reset();telemetry.Start(reading=>Dispatcher.BeginInvoke(DispatcherPriority.Background,(Action)(()=>{if(version==revision&&IsVisible)Update(reading);})),error:message=>Dispatcher.BeginInvoke((Action)(()=>{if(version==revision&&IsVisible){live.Text="Collecte indisponible · réouvre le panneau";live.Foreground=UI.Brush("#F3CF91");live.ToolTip=message;}})));}catch(Exception ex){Store.Log("Cycle état PC: "+ex);}finally{lifecycle.Release();}}
    void Update(PcReading value){latest=value;live.Text="●  En direct · "+value.At.ToString("HH:mm:ss");live.Foreground=UI.Brush("#A0E7CF");cpu.Update(value.Cpu, value.CpuTemperature,value.CpuName,LoadHint(value.Cpu));
        var device=value.Gpus.OrderByDescending(g=>g.Load??-1).FirstOrDefault();gpu.Update(device?.Load,device?.Temperature,device?.Name??"Aucune carte détectée",device?.MemoryUsedMb is double used&&device.MemoryTotalMb is double total?"Vidéo : "+(used/1024).ToString("0.0")+" / "+(total/1024).ToString("0")+" Go":"Sonde selon le pilote");gpu.Root.ToolTip=string.Join("\n",value.Gpus.Select(g=>g.Name+" · "+Pct(g.Load)+" · "+Temp(g.Temperature)));
        double? memoryPercent=value.MemoryTotal>0?100.0*(value.MemoryTotal-value.MemoryAvailable)/value.MemoryTotal:null;ramValue.Text=Pct(memoryPercent);ramDetail.Text=value.MemoryTotal>0?Bytes(value.MemoryTotal-value.MemoryAvailable)+" / "+Bytes(value.MemoryTotal)+" utilisés":"Mesure indisponible";ramGraph.Push(memoryPercent);ramHeat.Text=value.MemoryHeat.Length>0?string.Join("     ",value.MemoryHeat.Select((h,i)=>"Barrette "+(i+1)+" · "+Temp(h.Temperature))):"Température : aucune sonde de barrette accessible";ramHeat.ToolTip=string.Join("\n",value.MemoryHeat.Select(h=>h.Name+" · "+Temp(h.Temperature)));
        diskValue.Text=Pct(value.DiskBusy)+" actifs";diskRates.Text="Lecture "+Rate(value.DiskRead)+"     Écriture "+Rate(value.DiskWrite);diskGraph.Push(value.DiskBusy);UpdateStorage(value);
        networkValue.Text="↓ "+Rate(value.Download);networkUp.Text="↑ "+Rate(value.Upload);networkName.Text=value.Network;networkGraph.Push(value.Download,value.Upload);networkGraph.ToolTip="Cyan : réception · violet : envoi";
        foot.Text="1 relevé/s · sondes 3 s · disques 30 s";cpu.Heat.ToolTip=string.IsNullOrWhiteSpace(value.SensorNote)?"Température réelle du processeur · relevée toutes les 3 secondes":value.SensorNote;
    }
    void UpdateStorage(PcReading value){string key=string.Join("|",value.Drives.Select(d=>d.Name+":"+d.Free))+string.Join("|",value.StorageHeat.Select(h=>h.Name+":"+h.Temperature));if(storageKey==key)return;storageKey=key;driveRows.Children.Clear();foreach(var drive in value.Drives){double used=drive.Total>0?1.0-(double)drive.Free/drive.Total:0;var row=new Grid{Margin=new Thickness(0,3,0,3)};row.ColumnDefinitions.Add(new(){Width=new GridLength(30)});row.ColumnDefinitions.Add(new(){Width=new GridLength(1,GridUnitType.Star)});row.ColumnDefinitions.Add(new(){Width=new GridLength(117)});row.Children.Add(UI.Text(drive.Name.TrimEnd('\\'),10,null,true));var track=new Grid{Height=5,VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(6,0,12,0)};track.Children.Add(new Border{CornerRadius=new CornerRadius(3),Background=UI.Brush("#19FFFFFF")});var fill=new Border{CornerRadius=new CornerRadius(3),Background=UI.Brush(used>.9?"#F3B58D":"#E8C58B"),HorizontalAlignment=HorizontalAlignment.Left};track.Children.Add(fill);track.SizeChanged+=(_,_)=>fill.Width=track.ActualWidth*used;Grid.SetColumn(track,1);row.Children.Add(track);var free=UI.Text(Bytes(drive.Free)+" libres",10,UI.Dim);free.TextAlignment=TextAlignment.Right;Grid.SetColumn(free,2);row.Children.Add(free);row.ToolTip=drive.Name+" · "+Bytes(drive.Total-drive.Free)+" utilisés sur "+Bytes(drive.Total);driveRows.Children.Add(row);}storageHeat.Children.Clear();foreach(var h in value.StorageHeat){var text=UI.Text(h.Name.Trim()+"  ·  "+Temp(h.Temperature),9,UI.Dim);text.TextTrimming=TextTrimming.CharacterEllipsis;storageHeat.Children.Add(text);}if(value.Drives.Length==0)driveRows.Children.Add(UI.Text("Aucun volume fixe accessible",11,UI.Dim));}
